/* rinvoq-hcp brand styles */
@import 'tokens.css';
@import 'fonts.css';

/* RINVOQ HCP — Brand-specific style overrides */

/* Section: glacier — matches live site resource-container--gold + section-bg-brushstroke + gradient--white-glacier */
.section.glacier {
  position: relative;
  padding: 48px 0 220px;
  overflow: visible;
  max-width: none;
  width: 100%;
  margin-left: 0;
  margin-right: 0;
}

.section.glacier::before {
  content: '';
  position: absolute;
  z-index: -1;
  top: 50px;
  bottom: -50px;
  left: 0;
  right: 0;
  background-color: #fff;
  pointer-events: none;
}

.section.glacier::after {
  content: '';
  position: absolute;
  z-index: -1;
  top: 0;
  left: 0;
  width: 100%;
  height: calc(100% + 12px);
  background-image: url('data:image/svg+xml;base64,');
  background-repeat: no-repeat;
  background-size: cover;
  pointer-events: none;
}

.section.glacier > * {
  position: relative;
  z-index: 1;
}

.section.glacier .default-content-wrapper h2 {
  font-family: var(--body-font-family);
  font-size: 24px;
  font-weight: 600;
  line-height: 30px;
  color: var(--color-charcoal, #25282a);
  text-align: center;
  margin: 0 0 16px;
  position: relative;
  display: inline-block;
}

.section.glacier .default-content-wrapper {
  text-align: center;
  margin-bottom: 24px;
  padding: 0 20px;
}

.section.glacier .default-content-wrapper:last-of-type {
  text-align: left;
  width: 100%;
  max-width: 1180px;
  margin: 4px auto 0;
  padding: 0 20px;
}

.section.glacier .default-content-wrapper:last-of-type p {
  font-size: 14px;
  font-style: normal;
  margin: 0;
}

.section.glacier .default-content-wrapper h2::after {
  content: '';
  display: block;
  position: relative;
  margin-top: 8px;
  width: 100%;
  height: 6px;
  background-image: url('data:image/svg+xml;base64,');
  background-size: 100%;
  background-repeat: no-repeat;
  background-position: 0 0;
}

@media (min-width: 986px) {
  .section.glacier {
    margin: 32px 0;
    padding: 32px 0 64px;
  }

  .section.glacier::before {
    top: 35px;
    bottom: -35px;
  }

  .section.glacier::after {
    height: 100%;
    background-size: 100% 110%;
    background-position: center;
  }

  .section.glacier .default-content-wrapper h2 {
    font-size: 32px;
    line-height: 40px;
  }

  .section.glacier .default-content-wrapper {
    padding: 0;
  }
}

/* Section: text-container — full-width so block controls its own centering */
.section.text-container-container {
  max-width: none;
  width: 100%;
  margin-bottom: 0;
  background-color: var(--color-glacier, #f5f5f5);
  padding-top: 24px;
  padding-bottom: 24px;
  margin-left: 0;
  margin-right: 0;
}

.section.text-container-container + .section.text-container-container {
  margin-top: 0;
  padding-top: 0;
}

/* Hero: brushstroke underline on TREATMENT GOALS (strong after em) */
.hero.no-padding h1 strong {
  position: relative;
  display: inline-block;
}

.hero.no-padding h1 strong::after {
  content: '';
  position: absolute;
  bottom: var(--hero-stroke-bottom-offset, -15px);
  left: 0;
  width: 100%;
  height: var(--hero-stroke-height, 22px);
  background-image: url('data:image/svg+xml;base64,');
  background-position: center;
  background-repeat: no-repeat;
  background-size: 100% auto;
}

/* Hero homepage: constrain height and position bg absolutely */
.hero.no-padding {
  position: relative;
  overflow: hidden;
  min-height: 340px;
}

.hero.no-padding > div:first-child {
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 0;
  pointer-events: none;
}

.hero.no-padding > div:first-child img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  position: absolute;
  top: 0;
  left: 0;
  transform: none;
}

.section.hero-container:not(.dosing-hero) .hero.no-padding {
  overflow: visible;
}

.section.hero-container:not(.dosing-hero) .hero.no-padding > div:first-child {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 900px;
  overflow: visible;
  z-index: -1;
}

.section.hero-container:not(.dosing-hero) .hero.no-padding > div:first-child img {
  width: 3100px;
  max-width: none;
  height: auto;
  object-fit: unset;
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
}

/* Hero homepage: inner content flex row — text left, badge right */
.hero.no-padding .hero-text-container {
  position: relative;
  z-index: 1;
}

.hero.no-padding .hero-text-container .cmp-container-x-large {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: flex-start;
  min-height: 340px;
  padding: 20px 20px 0;
  max-width: 1220px;
  margin: 0 auto;
  width: 100%;
}

/* Hero: H1 line-height fix for mobile parity */
.hero.no-padding h1 {
  line-height: var(--hero-h1-line-height, 0.9);
}

/* Hero: expansion badge — hidden below 986px, visible on desktop right */
.hero.no-padding .hero-badge {
  display: none;
  margin: 0;
}

@media (min-width: 986px) {
  .hero.no-padding .hero-badge {
    display: block;
    flex-shrink: 0;
    margin-left: 40px;
  }

  .hero.no-padding .hero-badge img {
    width: 220px;
    height: auto;
  }
}

/* Dermatology hero: half-split section with ::before background */
.section:has(.hero.half-split-heading) {
  position: relative;
  overflow: hidden;
}

.section:has(.hero.half-split-heading)::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 692px;
  background-image: url('data:image/png;base64,');
  background-size: 3100px 692px;
  background-position: top center;
  background-repeat: no-repeat;
  z-index: -1;
}

/* First hero: heading only */
.hero.half-split-heading {
  position: relative;
  z-index: 1;
  min-height: 400px;
  display: flex;
  align-items: flex-end;
  background: none;
  overflow: visible;
}

.hero.half-split-heading h1 {
  font-size: 26px;
  line-height: 1.0625;
  font-weight: 600;
  font-style: normal;
  font-family: 'Graphik Bold', 'Helvetica Neue', arial, helvetica, sans-serif;
  color: var(--color-charcoal, #25282a);
}

.hero.half-split-heading h1 br {
  line-height: 0;
}

.hero.half-split-heading h1 em {
  font-family: 'Upa Handwriting', serif;
  font-style: normal;
  font-size: 58px;
  line-height: 0.9;
  display: block;
  color: var(--color-gold, #ffd100);
  margin: -5px 0 -10px;
}

.hero.half-split-heading h1 strong {
  font-size: 22px;
  font-weight: 600;
  position: relative;
  display: inline-block;
}


.hero.half-split-heading h1 strong::after {
  content: '';
  position: absolute;
  bottom: -15px;
  left: 0;
  width: 100%;
  height: 22px;
  background-image: url('data:image/svg+xml;base64,');
  background-position: center;
  background-repeat: no-repeat;
  background-size: 100% auto;
}

/* Second hero: CTA area with background image */
.hero.half-split-cta {
  position: relative;
  z-index: 1;
  min-height: auto;
  background: none;
  overflow: visible;
  margin: 0 auto;
}

.hero.half-split-cta > div:first-child {
  overflow: hidden;
}

.hero.half-split-cta .hero-text-container ~ div:first-of-type,
.hero.half-split-cta > div:first-child {
  position: relative;
  z-index: 0;
  margin: 0 !important;
  padding: 0 !important;
}

.hero.half-split-cta > div:not(:first-child):not(.hero-text-container) {
  display: none;
}

.hero.half-split-cta img {
  width: 100%;
  height: auto;
  display: block;
  max-width: none;
}

.hero.half-split-cta .hero-text-container {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  z-index: 1;
}

.hero.half-split-cta .cmp-container-x-large {
  padding: 20px;
}


.hero.half-split-cta h3 {
  font-size: 24px;
  font-family: Graphik, 'Helvetica Neue', arial, helvetica, sans-serif;
  font-weight: 600;
  font-style: normal;
  color: #fff;
  line-height: 0.5;
  margin: 0;
}

.hero.half-split-cta h3 em {
  font-size: 14px;
  font-style: normal;
  font-weight: 600;
  display: block;
  margin-bottom: 2px;
}

.hero.half-split-cta p {
  margin: 8px 0 0;
}

.hero.half-split-cta a.button {
  display: inline-flex;
  align-items: center;
  background-color: var(--color-brand-primary, #90124a);
  color: #fff;
  padding: 16px 47px 16px 32px;
  border-radius: 100px;
  font-family: 'Graphik Medium', 'Helvetica Neue', arial, helvetica, sans-serif;
  font-size: 16px;
  font-style: normal;
  font-weight: 700;
  text-decoration: none;
  border: none;
  position: relative;
}

.hero.half-split-cta a.button:hover {
  background: var(--color-brand-primary, #90124a);
  background-image: radial-gradient(#d66d92 0%, var(--color-brand-primary, #90124a) 157%);
  background-position: 100% 50%;
  background-size: 400% 100%;
  color: #fff;
  transform: scale(1.0125);
  animation: shine 1s linear forwards;
}

@keyframes shine {
  0% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.hero.half-split-cta a.button::after {
  content: '';
  display: inline-block;
  width: 20px;
  height: 20px;
  background: url('data:image/svg+xml;base64,') no-repeat center;
  background-size: contain;
  position: absolute;
  right: 24px;
  top: 50%;
  transform: translateY(-50%);
}

@media (min-width: 900px) {
  .section:has(.hero.half-split-heading) {
    min-height: auto;
  }

  .hero.half-split-heading {
    min-height: auto;
  }

  .hero.half-split-heading .hero-text-container {
    min-height: 320px;
  }

  .hero.half-split-heading h1 {
    font-size: 40px;
    line-height: 36px;
  }

  .hero.half-split-heading h1 em {
    font-size: 100px;
  }

  .hero.half-split-heading h1 strong {
    font-size: 40px;
  }

  .hero.half-split-heading .cmp-container-x-large {
    padding-top: 64px;
    max-width: 1180px;
    width: 100%;
    margin: 0 auto;
  }

  .hero.half-split-cta {
    max-width: 1180px;
    aspect-ratio: 2274 / 542;
  }

  .hero.half-split-cta .cmp-container-x-large {
    padding: 85px 32px;
    margin-left: -100px;
  }
}

/* Tablet (900–984px ONLY) — placed AFTER the `@media (min-width: 900px)` block
   so these rules win by source order. The desktop block above forces a tall
   heading text-container (320px) and a wide-thin CTA banner (aspect-ratio
   2274/542 + max-width 1180), but live at tablet shows: a SHORT heading region
   that hugs its content (~191px), and the CTA banner displaying the mobile
   image at its intrinsic 670×440 (object-fit:fill, container hugging the
   image) — NOT cropped/stretched into an aspect-ratio box. Lower bound 900px
   avoids colliding with the `@media (max-width: 899px)` mobile block below
   (which pins img+container to 230px). Desktop (>=985px) is untouched. */
@media (min-width: 900px) and (max-width: 984px) {
  .hero.half-split-heading .hero-text-container {
    min-height: auto;
  }

  .hero.half-split-cta {
    max-width: none;
    aspect-ratio: auto;
  }

  .hero.half-split-cta > div:first-child {
    padding-left: 40px !important;
    padding-right: 40px !important;
    min-height: 0;
    display: flex;
    justify-content: center;
  }

  .hero.half-split-cta img {
    width: auto;
    max-width: 100%;
    height: auto;
    object-fit: fill;
  }

  .hero.half-split-cta .hero-text-container {
    display: flex !important;
    align-items: center;
  }

  .hero.half-split-cta .hero-text-container .cmp-container-x-large {
    padding: 20px 32px 20px 60px;
    margin-left: 0;
  }
}

@media (max-width: 899px) {

  .section:has(.hero.half-split-heading)::before {
    position: absolute;
    z-index: -1;
    top: 0;
    left: 0;
    display: block;
    width: 100%;
    height: 100%;
    background-image: url('data:image/png;base64,');
    background-repeat: no-repeat;
    background-size: 100%;
    background-position: top center;
    content: '';
  }

  .hero.half-split-heading {
    min-height: auto;
    overflow: visible;
  }

  .hero.half-split-heading .hero-text-container {
    position: static;
    display: block;
    /* Reset base hero.css min-height:368px (applied >=744px) so the heading
       band hugs its content on 744–899px tablets instead of a tall empty box. */
    min-height: auto;
  }

  .hero.half-split-heading .cmp-container-x-large {
    padding: 0 46px 42px;
  }

  .hero.half-split-heading h1 em {
    line-height: 1.2;
  }

  .hero.half-split-heading h1 strong {
    line-height: 1.5;
  }

  .hero.half-split-heading > div:not(.hero-text-container) {
    display: none;
  }

  .section.hero-container:has(.hero.half-split-heading) {
    display: flex;
    flex-direction: column;
    padding: 64px 20px 0;
    overflow: visible;
  }

  .hero.half-split-cta {
    overflow: visible;
    aspect-ratio: auto;
    border-radius: 0;
    max-width: none;
    margin-bottom: 48px;
  }

  .hero.half-split-cta a.button::after {
    right: 15px;
  }

  .hero.half-split-cta > div:first-child {
    overflow: hidden;
    /* Hug the image (which keeps its 670:440 aspect ratio) — matches live,
       which shows the mobile image at natural 670×440 on tablet and scales it
       down proportionally on phones. Reset the base hero.css min-height:368px
       (applied at >=744px) so the wrapper follows the image, no empty gap. */
    height: auto;
    min-height: 0;
    display: flex;
    justify-content: center;
  }

  .hero.half-split-cta img {
    /* Natural size, capped to container width, aspect ratio preserved (NOT
       stretched to a fixed 230px height). Live: 670×440 on tablet, ~350×230
       on a 390px phone — proportional throughout. */
    width: auto;
    max-width: 100%;
    height: auto;
    border-radius: 0;
    object-fit: fill;
  }

  .hero.half-split-cta .hero-text-container {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 1;
  }

  .hero.half-split-cta .cmp-container-x-large {
    padding: 45px 20px 20px;
    margin-left: 0;
  }

  .hero.half-split-cta h3 {
    color: var(--color-charcoal, #25282a);
    font-size: 20px;
    font-family: Graphik, 'Helvetica Neue', arial, helvetica, sans-serif;
    font-weight: 600;
    line-height: 25px;
    margin: 0;
  }

  .hero.half-split-cta h3 em {
    font-size: 14px;
    font-weight: 600;
    line-height: 17.5px;
    display: inline;
    margin-bottom: 0;
  }

  .hero.half-split-cta p {
    margin: 0;
  }

  .hero.half-split-cta a.button {
    margin-top: 12px;
    font-size: 16px;
    font-family: 'Graphik Medium', 'Helvetica Neue', arial, helvetica, sans-serif;
    font-weight: 700;
    padding: 12px 40px 12px 24px;
  }
}

/* Tablet (744–899px ONLY): the shared `@media (max-width: 899px)` block above
   top-aligns the CTA text overlay (padding-top:45px) — correct for phones, but
   on tablet the overlay should be VERTICALLY CENTERED over the banner image and
   shifted slightly right (like the 900–984px block), matching live. Placed
   AFTER the ≤899px block so it wins by source order; lower bound 744px keeps
   true phones (≤743px) on the top-aligned treatment. */
@media (min-width: 744px) and (max-width: 899px) {
  .hero.half-split-cta .hero-text-container {
    display: flex;
    align-items: center;
  }

  .hero.half-split-cta .cmp-container-x-large {
    padding: 20px 32px 20px 60px;
    margin-left: 0;
  }
}


main > .section {
  margin-bottom: 0;
}

