  font-weight: 600;
  font-family: Graphik, 'Helvetica Neue', arial, helvetica, sans-serif;
  color: rgb(70, 72, 74);
  line-height: 30px;
  text-align: center;
  margin: 0;
  padding: 0;
  width: 100%;
