}

/* Row-label cells (first column) — Graphik 16px/24px regular, #000, left, top */
.section.label-highlights-table .table tbody td:first-child,
.section.label-highlights-table .table tbody td:first-child p {
  font-family: Graphik, 'Helvetica Neue', arial, helvetica, sans-serif;
  font-weight: 400;
  font-size: 16px;
  line-height: 24px;
  color: #000;
  text-align: left;
  vertical-align: top;
}

.section.label-highlights-table .table tbody td:first-child {
  padding: 12px 6px;
}

/* Dashed row divider — border-top on every cell of rows after the first */
.section.label-highlights-table .table tbody tr + tr td {
  border-top: 1px dashed rgba(0, 0, 0, 0.2);
}

/* Paragraph copy inside data cells — 14px */
.section.label-highlights-table .table tbody td p {
  font-size: 14px;
  line-height: 20px;
  margin: 0;
}

/* Bulleted lists inside data cells (Boxed Warnings, Warnings & Precautions, …) */
.section.label-highlights-table .table tbody td ul {
  margin: 4px 0 0;
  padding-left: 24px;
  list-style: disc;
}

.section.label-highlights-table .table tbody td li {
  font-family: Graphik, 'Helvetica Neue', arial, helvetica, sans-serif;
  font-weight: 400;
  font-size: 14px;
  line-height: 20px;
  margin-bottom: 4px;
}

/* Only the first list in the table (Boxed Warnings row) uses Graphik Semibold */
.section.label-highlights-table .table tbody tr:nth-child(3) td ul li {
  font-family: 'Graphik Semibold', 'Helvetica Neue', arial, helvetica, sans-serif;
}

/* Underlined sub-labels (e.g. "Serious Infections:") — first span in a cell/li */
.section.label-highlights-table .table tbody td li > span:first-child,
.section.label-highlights-table .table tbody td > span:first-child {
  border-bottom: 1px solid #000;
}

/* Footer "Please see…" rich-text below the table */
.section.label-highlights-table > .default-content-wrapper {
  max-width: 100%;
  margin: 16px 0 0;
}

.section.label-highlights-table > .default-content-wrapper p {
  font-family: Graphik, 'Helvetica Neue', arial, helvetica, sans-serif;
  font-size: 16px;
  line-height: 24px;
  color: rgb(37, 40, 42);
  margin: 0 0 4px;
}

.section.label-highlights-table > .default-content-wrapper a {
  font-family: 'Graphik Bold', 'Helvetica Neue', arial, helvetica, sans-serif;
  font-weight: 400;
  font-size: 16px;
  color: #90124a;
  text-decoration: none;
  border-bottom: 1px solid currentcolor;
}

/* §11 Engagement CTA — full-bleed gold band with torn brushstroke top/bottom
   edges (stroke--section-back.svg, gold #ffd100), centered chat icon + heading
   + body. Matches live's .section-bg-brushstroke gold callout. */
.section.level-up-cta {
  position: relative;
  width: 100vw;
  max-width: none;
  margin-left: calc(-50vw + 50%);
  margin-block: 32px;
  padding: 96px 24px;
  text-align: center;
}

.section.level-up-cta::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image: url('/content/dam/abbvie-eds-poc/stroke--section-back.svg');
  background-repeat: no-repeat;
  background-size: 100% 100%;
  background-position: center;
}

.section.level-up-cta .default-content-wrapper {
  max-width: 864px;
  margin-inline: auto;
}

.section.level-up-cta picture img {
  width: 104px;
  height: auto;
  display: block;
  margin: 0 auto 12px;
}

.section.level-up-cta h2 {
  font-family: 'Graphik Semibold', 'Helvetica Neue', arial, helvetica, sans-serif;
  font-size: 32px;
  line-height: 40px;
  font-weight: 600;
  color: rgb(37, 40, 42);
  text-transform: none;
  margin: 0;
}

.section.level-up-cta p {
  font-family: 'Graphik Semibold', 'Helvetica Neue', arial, helvetica, sans-serif;
  font-size: 24px;
  line-height: 28.8px;
  font-weight: 600;
  color: rgb(37, 40, 42);
  margin: 8px 0 0;
}

.section.level-up-cta p:has(img) {
  margin: 0;
}

/* §6/§7/§15/§16 efficacy chart images — live caps the wide superiority chart
   (1460px natural) to ~757px centered, NOT full-bleed. Cap chart images to a
   757px content width; smaller charts/flags keep natural size (max-width only).
   The monotherapy flag badge (435x115) is unaffected — it's below the cap. */
.section.h2h-period-efficacy picture img,
.section.switch-period-efficacy picture img,
.section.wpnrs-improvement picture img,
.section.easi-improvement picture img {
  width: auto;
  max-width: min(100%, 757px);
  height: auto;
  display: block;
  margin-inline: auto;
}

/* §13/§14 study-details: content sits in the 1180px column like other sections */
.section.level-up-study-details .table,
.section.measure-up-study-details .table {
  max-width: 1180px;
  margin-inline: auto;
}

/* Mobile: tables scroll horizontally (swipe), per brief */
@media (max-width: 899px) {
  .section.ae-comparison-table .flexbox-wrapper,
  .section.ae-comparison-table .flexbox,
  .section.ae-comparison-table .flexbox-item {
    max-width: 100%;
    min-width: 0;
  }

  .section.ae-comparison-table .flexbox-item[data-width='sixty'] .flexbox-item-content {
    max-width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .section.ae-comparison-table .swipe-text-copy {
    display: block;
  }

  .section.ae-comparison-table table {
    min-width: 718px;
  }

  .section.label-highlights-table .table {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .section.label-highlights-table .table table {
    min-width: 760px;
  }

  .section.level-up-hero .hero.no-padding .hero-text-container .cmp-container-x-large h1 {
    font-size: 26px;
    line-height: 26.88px;
  }
}
